// Migration du Zap "Demande de fournitures" (Typeform -> Gmail).
// Le formulaire Typeform contient 6 questions au titre IDENTIQUE
// ("Combien d'unites souhaitez-vous commander ?"), une par produit.
// On lit donc les reponses BRUTES (form_response) et on mappe chaque
// quantite a son produit en respectant l'ordre des champs du formulaire.

const body = $input.first().json;
const fr = body.form_response || body;
const fields = (fr.definition && fr.definition.fields) || [];
const answers = fr.answers || [];

// Valeur lisible d'une reponse Typeform quel que soit son type.
function answerValue(a) {
  if (!a) return '';
  switch (a.type) {
    case 'text': return a.text;
    case 'number': return a.number;
    case 'email': return a.email;
    case 'phone_number': return a.phone_number;
    case 'url': return a.url;
    case 'boolean': return a.boolean ? 'oui' : 'non';
    case 'date': return a.date;
    case 'choice': return (a.choice && (a.choice.label || a.choice.other)) || '';
    case 'choices': return ((a.choices && a.choices.labels) || []).join(', ');
    default: return a[a.type] != null ? a[a.type] : '';
  }
}

// Reponses rangees dans l'ordre d'affichage du formulaire.
const byId = {};
answers.forEach(a => { if (a.field && a.field.id) byId[a.field.id] = a; });
const titleById = {};
fields.forEach(f => { titleById[f.id] = f.title; });

const ordered = fields
  .map(f => ({ id: f.id, title: f.title, answer: byId[f.id] }))
  .filter(x => x.answer);

// Premiere reponse dont le titre correspond (champs uniques).
function firstByTitle(t) {
  const m = ordered.find(x => x.title === t);
  return m ? answerValue(m.answer) : '';
}

const campus     = firstByTitle('Quel est le nom du campus ?');
const demandeur  = firstByTitle('Quel est le nom du demandeur ?');
const remarques  = firstByTitle('Avez-vous des besoins ou remarques complementaires ?')
                || firstByTitle("Avez-vous des besoins ou remarques complémentaires ?");

// Les 6 quantites, dans l'ordre des champs du formulaire.
const quantites = ordered
  .filter(x => x.title === "Combien d'unites souhaitez-vous commander ?"
            || x.title === "Combien d’unités souhaitez-vous commander ?")
  .map(x => answerValue(x.answer));

// Ordre des produits identique au Zap d'origine.
const produits = [
  'ordinateur(s)',
  'double(s) ecran(s)',
  'souris',
  'clavier(s)',
  'casque(s)',
  'Chaise(s)',
];

const lignes = produits
  .map((label, i) => `- ${quantites[i] != null && quantites[i] !== '' ? quantites[i] : 0} ${label}`)
  .join('\n');

const subject = `Demande de fournitures - ${campus}`;

const message =
`Hello Julie,

${demandeur} a fait une demande pour le campus de ${campus}.

Il faut acheter :
${lignes}

Remarques supplementaires :
${remarques}

Bonne journee.`;

return [{ json: { to: 'julie@athena-bs.fr', subject, message, campus, demandeur } }];
